#!/bin/bash
# HL-055: render `Disclaimers.reviewNotes` to `docs/app-store-review-notes.txt`.
#
# The notes are a Swift multi-line literal with backslash continuations and one
# interpolation, so there is no verbatim to copy out of `Disclaimers.swift` — the
# rendered file is what the submission checklist tells Christian to paste. It was
# regenerated by hand, and stayed at its 2026-09-05 text through two rewrites of the
# source (HL-051, HL-055): a reviewer would have read the WidgetKit line the round-2
# fix removed. So the file is now generated here and **checked**: `--check` fails when
# the file on disk is not what the source renders to, and `gate.sh` runs it. The
# Swift test `renderedReviewNotesMatchTheSource` closes the other half — it compares
# the same file to the real `Disclaimers.reviewNotes` value, so this renderer cannot
# drift from Swift's own rules either.
set -euo pipefail
cd "$(dirname "$0")/.."

python3 - "${1:-}" << 'PYEOF'
import json, re, sys

SOURCE = "Packages/LaborKit/Sources/LaborKit/Disclaimers.swift"
CATALOG = "Packages/LaborKit/Sources/LaborKit/Resources/Localizable.xcstrings"
OUT = "docs/app-store-review-notes.txt"

swift = open(SOURCE, encoding="utf-8").read()
start = swift.index("public static var reviewNotes: String {")
body = swift[swift.index('"""\n', start) + 4:]
closing = re.search(r'\n( *)"""', body)
body, indent = body[:closing.start()], closing.group(1)

# Swift's rules for the literal: strip the closing delimiter's indentation from every
# line, and a trailing backslash joins the line to the next.
lines = [line[len(indent):] if line.startswith(indent) else line.lstrip()
         for line in body.split("\n")]
text = "\n".join(lines).replace("\\\n", "")

# The one interpolation is the shipped disclaimer, read from the String Catalog's
# source string — which is what `String(localized:)` returns for English.
strings = json.load(open(CATALOG, encoding="utf-8"))["strings"]
key = next(k for k in strings if k.startswith("A stopwatch with arithmetic"))
text = text.replace("\\(measuredNotDiagnosed)", key)
assert "\\(" not in text, "an interpolation this renderer does not know"

if sys.argv[1] == "--check":
    current = open(OUT, encoding="utf-8").read()
    if current != text:
        print(f"FAIL — {OUT} is stale: run ./scripts/render-review-notes.sh and commit it")
        sys.exit(1)
    print(f"PASS — {OUT} matches Disclaimers.reviewNotes ({len(text)} characters)")
else:
    open(OUT, "w", encoding="utf-8").write(text)
    print(f"rendered {OUT}: {len(text)} characters")
PYEOF
